/**
 * Seasonal polar plots inside “Explore more…”.
 * Sites listed in polar-seasonal-sites.json (generated by the R batch) get
 * the season picker; others show a coming-soon message. Empty season
 * summaries stay hidden.
 */
import { polarSeasonalImageUrl } from './polar-image-url.js';
import { getSeasonalReading } from './polar-readings.js';

const SEASONAL_SITES_URL = `${import.meta.env.BASE_URL || '/'}polar-seasonal-sites.json`;

/** Fallback before / without the manifest (CLDP0299 has always shipped). */
const SEASONAL_SITES_FALLBACK = new Set(['CLDP0299']);

const SEASONS = {
    winter: {
        label: 'Winter 2025',
        range: 'Dec 2024 – Feb 2025',
    },
    spring: {
        label: 'Spring 2025',
        range: 'Mar–May 2025',
    },
    summer: {
        label: 'Summer 2025',
        range: 'Jun–Aug 2025',
    },
    autumn: {
        label: 'Autumn 2025',
        range: 'Sep–Nov 2025',
    },
};

let seasonalSitesCache = null;

async function loadSeasonalSites() {
    if (seasonalSitesCache) return seasonalSitesCache;
    try {
        const res = await fetch(SEASONAL_SITES_URL);
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const data = await res.json();
        const list = Array.isArray(data) ? data : data?.sites;
        seasonalSitesCache = new Set(
            (list || []).map((code) => String(code).toUpperCase()).filter(Boolean)
        );
        if (seasonalSitesCache.size === 0) {
            seasonalSitesCache = new Set(SEASONAL_SITES_FALLBACK);
        }
    } catch (err) {
        console.warn('Seasonal sites manifest not available:', err);
        seasonalSitesCache = new Set(SEASONAL_SITES_FALLBACK);
    }
    return seasonalSitesCache;
}

function currentPollutant(slot) {
    return slot?.dataset?.pollutant === 'pm25' ? 'pm25' : 'no2';
}

function pollutantLabel(key) {
    return key === 'pm25' ? 'PM₂.₅' : 'NO₂';
}

/**
 * @param {{ sitecode: string, slot?: HTMLElement | null }} options
 * @returns {Promise<{ setPollutant: (pollutant: string) => void } | undefined>}
 */
export async function initPolarSeasonalPlots({
    sitecode,
    slot = document.getElementById('polar-plot-slot'),
} = {}) {
    const root = document.getElementById('polar-seasonal');
    if (!root) return;

    const available = document.getElementById('polar-seasonal-available');
    const soon = document.getElementById('polar-seasonal-soon');
    const img = document.getElementById('polar-seasonal-img');
    const resultRange = document.getElementById('polar-seasonal-result-range');
    const caption = document.getElementById('polar-seasonal-caption');
    const summary = document.getElementById('polar-seasonal-summary');
    const presets = root.querySelectorAll('.polar-seasonal__preset');

    if (!available || !soon || !img) return;

    const code = (sitecode || '').toUpperCase();
    const sites = await loadSeasonalSites();
    const hasSeasonal = sites.has(code);

    available.hidden = !hasSeasonal;
    soon.hidden = hasSeasonal;

    if (!hasSeasonal) {
        if (summary) {
            summary.hidden = true;
            summary.textContent = '';
        }
        return {
            setPollutant() {},
        };
    }

    let activeSeason = 'winter';

    function setSeason(name) {
        if (!SEASONS[name]) return;
        activeSeason = name;
        presets.forEach((btn) => {
            btn.classList.toggle('is-active', btn.dataset.season === activeSeason);
        });
        showPlot();
    }

    function showPlot(pollutant = currentPollutant(slot)) {
        const key = pollutant === 'pm25' ? 'pm25' : 'no2';
        const meta = SEASONS[activeSeason];
        const url = polarSeasonalImageUrl(code, key, activeSeason);

        img.src = url;
        img.alt = `Polar plot of ${pollutantLabel(key)} for ${code}, ${meta.label}`;
        if (resultRange) resultRange.textContent = `${pollutantLabel(key)} · ${meta.label}`;
        if (caption) caption.textContent = meta.range;

        if (summary) {
            const text = getSeasonalReading(code, key, activeSeason);
            if (text) {
                summary.textContent = text;
                summary.hidden = false;
            } else {
                summary.textContent = '';
                summary.hidden = true;
            }
        }
    }

    presets.forEach((btn) => {
        btn.addEventListener('click', () => setSeason(btn.dataset.season));
    });

    setSeason(activeSeason);

    return {
        setPollutant(pollutant) {
            showPlot(pollutant);
        },
    };
}
